#!/usr/bin/env python3
from __future__ import annotations

import json
import hashlib
import sys
from copy import deepcopy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
S = ROOT / "research" / "strominger"
sys.path.insert(0, str(S))

from partial_repair_compiler import compile_contract  # noqa: E402


contract_path = S / "contracts" / "dependency-aware-partial-repairs.v1.json"
result_path = S / "results" / "dependency_aware_partial_repairs.json"
contract = json.loads(contract_path.read_text(encoding="ascii"))
result = compile_contract(contract)
models = {model["id"]: model for model in result["models"]}


def theta_frontier_variant(
    with_valuation_extension: bool,
    with_clark_family: bool,
    authorized_swap_pairs: tuple[tuple[str, str], ...] = (),
) -> dict:
    candidate = deepcopy(contract)
    triangle = candidate["theta_repair_triangle"]
    if with_valuation_extension:
        triangle["source_capabilities"].append("valuation_completion_extension")
        triangle["valuation_boundary_constructor"]["joint_rigged_completion_extension_authorized"] = True
        triangle["valuation_boundary_constructor"]["lane_completion_profiles"]["primitive_exponential_laplace:front_odd"]["constructor_authorized"] = True
        triangle["valuation_boundary_constructor"]["relative_moment_constructor"]["constructor_status"] = "source_authorized_exact_identity"
        valuation = next(operation for operation in triangle["operations"] if operation["repair_id"] == "L")
        valuation["completion_scope"] = "source_authorized_completion_extension"
        valuation["missing_source_constructor"] = None
    if with_clark_family:
        triangle["clark_uniform_constructor_family"] = {
            "family_id": "F_source_fixture",
            "source_authority_root": "theta_valuation_constructor_monoid",
            "fixed_finite": True,
            "uniformly_dominates_current_matrices": True,
        }
    for pair in authorized_swap_pairs:
        declaration = next(
            item for item in triangle["commutation_declarations"]
            if frozenset(item["pair"]) == frozenset(pair)
        )
        declaration.update({
            "authorized": True,
            "source_authority_root": "theta_triangle_comparison_fixture",
            "comparison_cell": "typed_complete_packet_comparison:" + "-".join(pair),
        })
    triangle["expected"]["admissible_order_count"] = 3 if with_valuation_extension and with_clark_family else 0
    triangle["expected"]["typed_endpoint_count"] = 1 if with_valuation_extension and with_clark_family else 0
    triangle["expected"]["authorized_adjacent_swap_count"] = len(authorized_swap_pairs)
    compiled = compile_contract(candidate)["theta_repair_triangle"]
    admissible_orders = [tuple(path["order"]) for path in compiled["paths"] if path["dynamically_admissible"]]
    authorized_pairs = {
        frozenset(declaration["pair"])
        for declaration in triangle["commutation_declarations"]
        if declaration.get("authorized")
    }
    adjacency = {order: set() for order in admissible_orders}
    for order in admissible_orders:
        for index in range(len(order) - 1):
            if frozenset((order[index], order[index + 1])) not in authorized_pairs:
                continue
            swapped = list(order)
            swapped[index], swapped[index + 1] = swapped[index + 1], swapped[index]
            swapped = tuple(swapped)
            if swapped in adjacency:
                adjacency[order].add(swapped)
                adjacency[swapped].add(order)
    component_count = 0
    unseen = set(admissible_orders)
    while unseen:
        component_count += 1
        frontier = [unseen.pop()]
        while frontier:
            current = frontier.pop()
            for neighbor in adjacency[current]:
                if neighbor in unseen:
                    unseen.remove(neighbor)
                    frontier.append(neighbor)
    return {
        "valuation_extension_supplied": with_valuation_extension,
        "clark_family_supplied": with_clark_family,
        "admissible_order_count": compiled["observed"]["admissible_order_count"],
        "typed_endpoint_count": compiled["observed"]["typed_endpoint_count"],
        "admissible_orders": [list(order) for order in admissible_orders],
        "authorized_adjacent_swap_count": compiled["observed"]["authorized_adjacent_swap_count"],
        "coherence_component_count": component_count,
    }


